Action: run_sql({'query': 'SELECT \n    CORR(e.avg_rating, v_stats.violations_per_inspection) as corr_rating_violations_per_insp,\n    CORR(e.avg_rating, v_stats.critical_per_inspection) as corr_rating_critical_per_insp,\n    CORR(e.avg_rating, v_stats.avg_score) as corr_rating_avg_score\nFROM establishments e\nJOIN (\n    SELECT \n        i.slchd_establishment_key,\n        COUNT(DISTINCT i.inspection_id) as num_inspections,\n        AVG(i.inspection_score) as avg_score,\n        CAST(COUNT(v.violation_id) AS DOUBLE) / COUNT(DISTINCT i.inspection_id) as violations_per_inspection,\n        CAST(SUM(CASE WHEN vc.critical THEN 1 ELSE 0 END) AS DOUBLE) / COUNT(DISTINCT i.inspection_id) as critical_per_inspection\n    FROM inspections i\n    LEFT JOIN violations v ON i.inspection_id = v.inspection_id\n    LEFT JOIN violation_codes vc ON v.violation_code_id = vc.violation_code_id\n    GROUP BY i.slchd_establishment_key\n) v_stats ON e.slchd_establishment_key = v_stats.slchd_establishment_key\nWHERE e.avg_rating IS NOT NULL;'})

